c74object.discussion:
Minimal v8 or v8ui script, with the helper javascript/ossia.v8connector.js and an [ossia.v8connector synth] whose scripting name is "synth" and whose left outlet is patched into the script:


const OssiaConnector = require("ossia.v8connector");


const synth = new OssiaConnector("synth");


function loadbang() {


  synth.declare({ gain: { type: "float", min: -60, max: 6, unit: "gain.db", default: -12 } });


  synth.on("gain", (v) => { post("gain", v, "\n"); });


}


function anything() { synth.dispatch(messagename, arrayfromargs(arguments)); }


function bang() { synth.set("gain", -6); }


The helper keeps the declarations and replays them when the object sends "ready", so the object can be deleted and recreated. bind("other/address") follows a parameter declared elsewhere instead of creating one.
